tool_and_message_events.command:
/bin/bash -lc 'review_dir="$(mktemp -d "$PWD/.desk-review.XXXXXXXX")" &&
cp -R release "$review_dir/" &&
(
  cd "$review_dir/release" &&
  npm install --offline --ignore-scripts --no-audit --no-fund --cache "$review_dir/npm-cache" ../../vendor/hono-4.13.19.tgz &&
  npm ls hono --depth=0 &&
  npm test &&
  node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import test from 'node:test';
import app from './app.mjs';

const session = { 'x-shift': 'day' };
const cases = [
  { name: 'existing valid record', id: 'k8', headers: session, status: 200, steps: 'dispatch,session,read' },
  { name: 'missing session', id: 'k8', status: 401, error: 'sign_in', steps: 'dispatch,session' },
  { name: 'missing record', id: 'missing', headers: session, status: 404, error: 'not_found', steps: 'dispatch,session,read' },
  { name: 'supplied invalid record', id: 'm3', headers: session, status: 502, error: 'invalid_record', steps: 'dispatch,session,read,error' },
];

for (const scenario of cases) {
  test(scenario.name, async () => {
    const response = await app.request('/desk/' + scenario.id, { method: 'GET', headers: scenario.headers });
    assert.ok(response instanceof Response);
    const raw = await response.text();
    const actual = {
      status: response.status,
      mediaType: response.headers.get('content-type'),
      steps: response.headers.get('x-desk-steps'),
      body: JSON.parse(raw),
    };
    console.log(JSON.stringify({ scenario: scenario.name, ...actual }));
    assert.equal(actual.status, scenario.status);
    assert.equal(actual.steps, scenario.steps);
    if (scenario.error) {
      assert.equal(actual.body.error, scenario.error);
    } else {
      assert.match(actual.mediaType, /"'^application'"\\/json(?:;|"'$)/i);
      assert.deepEqual(Object.keys(actual.body).sort(), ['"'id', 'title']);
      assert.equal(actual.body.id, scenario.id);
      assert.equal(typeof actual.body.title, 'string');
      assert.ok(actual.body.title.length > 0);
    }
  });
}
NODE
)
review_status="'$?
if [ -n "$review_dir" ]; then
  rm -r -- "$review_dir"
fi
exit "$review_status"'

